{
  "references": [
    {
      "id": "R1",
      "summary_ko": "그녀는 일어서서가 아니라 점프할 때 머리를 부딪칩니다."
    },
    {
      "id": "R2",
      "summary_ko": "그녀는 두 발로 상자 위에 서 있습니다."
    },
    {
      "id": "R3",
      "summary_ko": "벽에 걸린 머리 장식은 곰이 아니라 사자나 큰 고양이과 동물처럼 보입니다."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "점프하는 동안 사람의 머리와 벽/천장의 박제 동물 머리가 부자연스럽게 겹치고 변형됩니다."
    },
    {
      "id": "C2",
      "summary_ko": "점프하는 동안 사람의 머리와 천장에 달린 동물 머리가 비일관되게 겹치고 변형됩니다."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "R1은 점프 중 머리를 부딪치는 현상을 언급하고 C1은 점프 중 머리와 동물 머리가 겹쳐 변형되는 결함을 기술하여 연관성은 있으나 동일한 결함 설명인지 불확실합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "R1의 점프 중 머리 부딪침과 C2의 점프 중 머리와 동물 머리 간의 부자연스러운 변형은 부분적으로 관련되어 보이나 표현과 초점이 달라 동일 여부가 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "상자 위에 서 있는 발의 위치에 관한 내용과 머리 변형 결함은 서로 다른 대상과 현상을 다룹니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "상자 위에 두 발로 서 있다는 서술과 점프 중 머리가 변형되는 현상은 서로 다른 내용입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "벽에 걸린 동물 머리의 종류 식별에 관한 기술과 사람 머리와의 형태 왜곡/변형 결함은 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "동물 머리 장식의 종류에 대한 설명과 점프 중 발생하는 머리 모핑 결함은 대상 및 결함 내용이 다릅니다."
    }
  ]
}
